import collections
x = int(input())

def shr(a):
	while a % 2 == 0:
		a //= 2
	return a

def cal(n, ts, tt):
	d1 = collections.defaultdict(int)
	d2 = collections.defaultdict(int)
	for i in range(n):
		d1[shr(ts[i])] += 1
		d2[shr(tt[i])] += 1
	for i in d2.keys():
		t = d2[i]
		while i > 0:
			if i in d1:
				if t > d1[i]:
					t -= d1[i]
					del d1[i]
				elif t == d1[i]:
					del d1[i]
					t = 0
					break
				else:
					d1[i] -= t
					t = 0
					break
			i //= 2
		if t > 0:
			return False
	return True
for jj in range(x):
	n = int(input())
	ts = [int(i) for i in input().split(' ')]
	tt = [int(i) for i in input().split(' ')]
	if cal(n, ts, tt):
		print('YES')
	else:
		print('NO')
